package com.shopsphere;
import jakarta.servlet.http.HttpServletRequest;import java.time.Instant;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;
class ConflictException extends RuntimeException{ConflictException(String m){super(m);}}class UnauthorizedException extends RuntimeException{UnauthorizedException(String m){super(m);}}class NotFoundException extends RuntimeException{NotFoundException(String m){super(m);}}class BadRequestException extends RuntimeException{BadRequestException(String m){super(m);}}
record ApiError(Instant timestamp,int status,String error,String message,String path,Map<String,String> validationErrors){}
@RestControllerAdvice class GlobalExceptionHandler {@ExceptionHandler(MethodArgumentNotValidException.class)ResponseEntity<ApiError> validation(MethodArgumentNotValidException ex,HttpServletRequest r){Map<String,String> v=new LinkedHashMap<>();ex.getBindingResult().getFieldErrors().forEach(e->v.putIfAbsent(e.getField(),e.getDefaultMessage()));return response(HttpStatus.BAD_REQUEST,"Validation failed",r,v);}@ExceptionHandler(BadRequestException.class)ResponseEntity<ApiError> bad(BadRequestException e,HttpServletRequest r){return response(HttpStatus.BAD_REQUEST,e.getMessage(),r,Map.of());}@ExceptionHandler(ConflictException.class)ResponseEntity<ApiError> conflict(ConflictException e,HttpServletRequest r){return response(HttpStatus.CONFLICT,e.getMessage(),r,Map.of());}@ExceptionHandler({UnauthorizedException.class,org.springframework.security.oauth2.jwt.JwtException.class})ResponseEntity<ApiError> unauthorized(Exception e,HttpServletRequest r){return response(HttpStatus.UNAUTHORIZED,e.getMessage(),r,Map.of());}@ExceptionHandler(NotFoundException.class)ResponseEntity<ApiError> missing(NotFoundException e,HttpServletRequest r){return response(HttpStatus.NOT_FOUND,e.getMessage(),r,Map.of());}private ResponseEntity<ApiError> response(HttpStatus s,String m,HttpServletRequest r,Map<String,String> v){return ResponseEntity.status(s).body(new ApiError(Instant.now(),s.value(),s.getReasonPhrase(),m,r.getRequestURI(),v));}}
